layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); background-color: rgb(245, 245, 245); border-left: 5px solid var(--ryt-accent); border-radius: 0px; font-family: -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, Oxygen, Cantarell, "open sans", "helvetica neue", sans-serif, "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 14.88px; font-weight: 400; font-style: italic; line-height: 1.725; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 25px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { border-bottom: 1px solid rgb(239, 239, 239); border-radius: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 600; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, Oxygen, Cantarell, "open sans", "helvetica neue", sans-serif, "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 26.4px; font-weight: 700; font-style: normal; line-height: 1.725; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, Oxygen, Cantarell, "open sans", "helvetica neue", sans-serif, "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 13.76px; font-weight: 400; font-style: normal; line-height: 1.8; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, Oxygen, Cantarell, "open sans", "helvetica neue", sans-serif, "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 16px; font-weight: 700; font-style: normal; line-height: 1.725; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, Oxygen, Cantarell, "open sans", "helvetica neue", sans-serif, "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-weight: 600; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-accent); border-radius: 0px; font-family: -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, Oxygen, Cantarell, "open sans", "helvetica neue", sans-serif, "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 16px; font-weight: 600; font-style: normal; line-height: 1.8; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
